from pathlib import Path
import hashlib, json
import pandas as pd

ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'outputs/q4_v1/ablation/same_info'
FORMAL=ROOT/'outputs/q4_v1/stage4/q4_v1_slot_results.csv'
def sha(p):
 h=hashlib.sha256();
 with p.open('rb') as f:
  for b in iter(lambda:f.read(1<<20),b''): h.update(b)
 return h.hexdigest().upper()
def main():
 locked=pd.read_pickle(OUT/'checkpoints/locked_slots.pkl'); locked=locked[locked.date>='2025-02-01'].copy()
 rolling=pd.read_csv(FORMAL); rolling=rolling[rolling.policy=='问题4-3'].copy()
 keys=['date','slot']
 a=locked.groupby(keys,as_index=False).agg(locked_actual_cost=('actual_total_cost_yuan','sum'),locked_contract_cost=('contract_cost_yuan','sum'),locked_emergency_cost=('emergency_cost_yuan','sum'),locked_emergency_kwh=('emergency_purchase_kwh','sum'),locked_end_soc=('soc_end_kwh','last'))
 b=rolling.groupby(keys,as_index=False).agg(rolling_actual_cost=('actual_total_cost_yuan','sum'),rolling_contract_cost=('contract_cost_yuan','sum'),rolling_emergency_cost=('emergency_cost_yuan','sum'),rolling_emergency_kwh=('emergency_purchase_kwh','sum'),rolling_end_soc=('soc_end_kwh','last'))
 d=a.merge(b,on=keys); d['cost_diff_locked_minus_rolling']=d.locked_actual_cost-d.rolling_actual_cost; d['emergency_diff_locked_minus_rolling_kwh']=d.locked_emergency_kwh-d.rolling_emergency_kwh; d=d.sort_values(keys); d['cumulative_cost_diff']=d.cost_diff_locked_minus_rolling.cumsum()
 d.to_csv(OUT/'paired_daily_slot_comparison.csv',index=False,encoding='utf-8-sig')
 daily=d.groupby('date',as_index=False).agg(locked_actual_cost=('locked_actual_cost','sum'),rolling_actual_cost=('rolling_actual_cost','sum'),locked_contract_cost=('locked_contract_cost','sum'),rolling_contract_cost=('rolling_contract_cost','sum'),locked_emergency_cost=('locked_emergency_cost','sum'),rolling_emergency_cost=('rolling_emergency_cost','sum'),locked_emergency_kwh=('locked_emergency_kwh','sum'),rolling_emergency_kwh=('rolling_emergency_kwh','sum'),locked_end_soc=('locked_end_soc','last'),rolling_end_soc=('rolling_end_soc','last'))
 daily['cost_difference_locked_minus_rolling']=daily.locked_actual_cost-daily.rolling_actual_cost; daily['emergency_difference_locked_minus_rolling_kwh']=daily.locked_emergency_kwh-daily.rolling_emergency_kwh; daily['cumulative_cost_difference']=daily.cost_difference_locked_minus_rolling.cumsum(); daily['outcome']=daily.cost_difference_locked_minus_rolling.map(lambda x:'rolling_win' if x>1e-6 else 'locked_win' if x< -1e-6 else 'tie'); daily.to_csv(OUT/'paired_daily_comparison.csv',index=False,encoding='utf-8-sig')
 monthly=daily.assign(month=daily.date.str[:7]).groupby('month',as_index=False).agg(locked_actual_cost=('locked_actual_cost','sum'),rolling_actual_cost=('rolling_actual_cost','sum'),locked_contract_cost=('locked_contract_cost','sum'),rolling_contract_cost=('rolling_contract_cost','sum'),locked_emergency_cost=('locked_emergency_cost','sum'),rolling_emergency_cost=('rolling_emergency_cost','sum'),locked_emergency_kwh=('locked_emergency_kwh','sum'),rolling_emergency_kwh=('rolling_emergency_kwh','sum')); monthly['cost_difference_locked_minus_rolling']=monthly.locked_actual_cost-monthly.rolling_actual_cost; monthly['emergency_difference_locked_minus_rolling_kwh']=monthly.locked_emergency_kwh-monthly.rolling_emergency_kwh; monthly['cumulative_cost_difference']=monthly.cost_difference_locked_minus_rolling.cumsum(); monthly.to_csv(OUT/'paired_monthly_comparison.csv',index=False,encoding='utf-8-sig')
 ls=pd.read_pickle(OUT/'checkpoints/locked_solver.pkl'); fs=pd.read_csv(ROOT/'outputs/q4_v1/stage4/q4_v1_solver_quality.csv'); fs=fs[fs.policy=='问题4-3']; solver=pd.concat([ls.assign(branch='locked_same_info'),fs.assign(branch='rolling_formal_reused')],ignore_index=True); solver.to_csv(OUT/'paired_solver_quality.csv',index=False,encoding='utf-8-sig')
 summary={'formal_period_days':334,'formal_slots':len(locked),'locked_actual_cost_yuan':float(locked.actual_total_cost_yuan.sum()),'rolling_reused_actual_cost_yuan':float(rolling.actual_total_cost_yuan.sum()),'cost_saving_locked_minus_rolling_yuan':float(daily.cost_difference_locked_minus_rolling.sum()),'locked_contract_cost_yuan':float(locked.contract_cost_yuan.sum()),'rolling_contract_cost_yuan':float(rolling.contract_cost_yuan.sum()),'locked_emergency_cost_yuan':float(locked.emergency_cost_yuan.sum()),'rolling_emergency_cost_yuan':float(rolling.emergency_cost_yuan.sum()),'locked_emergency_kwh':float(locked.emergency_purchase_kwh.sum()),'rolling_emergency_kwh':float(rolling.emergency_purchase_kwh.sum()),'locked_end_soc_kwh':float(locked.soc_end_kwh.iloc[-1]),'rolling_end_soc_kwh':float(rolling.soc_end_kwh.iloc[-1]),'locked_inventory_corrected_from_6000_yuan':float(locked.actual_total_cost_yuan.sum()+6000-locked.soc_end_kwh.iloc[-1]),'rolling_inventory_corrected_from_6000_yuan':float(rolling.actual_total_cost_yuan.sum()+6000-rolling.soc_end_kwh.iloc[-1]),'rolling_win_days':int((daily.outcome=='rolling_win').sum()),'locked_win_days':int((daily.outcome=='locked_win').sum()),'tie_days':int((daily.outcome=='tie').sum()),'max_mip_gap_locked':float(ls.relative_gap.max()),'max_mip_gap_rolling_reused':float(fs.relative_gap.max()),'limit_feasible_locked':int((ls.solution_class=='time_limit_feasible_incumbent').sum()),'limit_feasible_rolling_reused':int((fs.solution_class=='time_limit_feasible_incumbent').sum()),'physical_and_cost_audit':'passed; see locked_vs_reused_rolling_validation.md'}
 (OUT/'final_paired_reuse_summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 before=json.loads((OUT/'protected_hashes_before.json').read_text(encoding='utf-8')); after={k:sha(ROOT/k) for k in before}; (OUT/'protected_hashes_after_locked_reuse.json').write_text(json.dumps(after,ensure_ascii=False,indent=2)+'\n',encoding='utf-8'); (OUT/'protected_hash_change_count.txt').write_text(str(sum(before[k]!=after[k] for k in before))+'\n',encoding='utf-8')
 print(json.dumps(summary,ensure_ascii=False,indent=2))
if __name__=='__main__': main()
